const response = $input.first().json;
const people = response.people || [];
const results = [];

for (const person of people) {
  let score = 0;

  // Score based on title
  const title = (person.title || '').toLowerCase();
  if (title.includes('ceo') || title.includes('coo') || title.includes('director')) score += 40;
  else if (title.includes('manager')) score += 20;
  else score += 5;

  // Score based on company size
  const empRange = person.organization?.estimated_num_employees || 0;
  if (empRange > 200) score += 30;
  else if (empRange > 50) score += 20;
  else if (empRange > 10) score += 10;

  // Score based on industry relevance
  const industry = (person.organization?.industry || '').toLowerCase();
  if (industry.includes('logistics') || industry.includes('transport')) score += 30;
  else if (industry.includes('manufacturing') || industry.includes('retail')) score += 20;
  else score += 0;

  // Assign tag
  let tag = 'cold';
  if (score >= 70) tag = 'high potential';
  else if (score >= 40) tag = 'warm';

  // Get best phone (Apollo may have mobile)
  const phone = person.phone_numbers?.[0]?.sanitized_number || '';

  if (!phone) continue; // Skip if no phone — WhatsApp requires phone

  results.push({
    json: {
      Name: person.name || '',
      Phone: phone,
      Company: person.organization?.name || '',
      Tag: tag,
      Stage: 'lead',
      Source: 'apollo',
      'Last Contacted': '',
      'Follow-up Due': '',
      'Response Status': 'no_reply',
      Notes: `Title: ${person.title || 'N/A'} | Score: ${score}`,
      'Assigned To': '',
      'Created Date': new Date().toISOString().split('T')[0],
      'WhatsApp Opt-Out': 'FALSE',
      'Apollo ID': person.id || '',
      'Lead Score': score,
      Industry: person.organization?.industry || '',
      Country: person.country || '',
      Email: person.email || ''
    }
  });
}

return results;

const newLeads = $('Extract and Score Leads').all();
const existingLeads = $input.all();

// Build set of existing Apollo IDs and phones
const existingApolloIds = new Set(existingLeads.map(l => l.json['Apollo ID']).filter(Boolean));
const existingPhones = new Set(existingLeads.map(l => l.json.Phone).filter(Boolean));

const unique = newLeads.filter(lead => {
  const apolloId = lead.json['Apollo ID'];
  const phone = lead.json.Phone;
  return !existingApolloIds.has(apolloId) && !existingPhones.has(phone);
});

return unique;

